const data = $input.first().json;

const emaCurrent = data.ema_current_status || 'UNKNOWN';
const emaPrev = data.ema_prev_status || 'UNKNOWN';
const emaStatusSeconds = data.ema_status_seconds || 0;

const actCurrent = data.act_current_status || 'UNKNOWN';
const actStatusSeconds = data.act_status_seconds || 0;

let alertType = 'NONE';
let message = '';

// El nodo EMA debe haber estado en OFFLINE continuos por al menos 10 minutos (600 a 660 segundos)
// para confirmar que no fue un micro-fallo transitorio de reconexión/reinicio.
const isConfirmedOfflineWindow = emaCurrent === 'OFFLINE' && emaStatusSeconds >= 600 && emaStatusSeconds < 660;

// CASO A: Sin Conexión WiFi / Apagón (EMA lleva >= 10m OFFLINE y Actuador lleva >= 5m OFFLINE)
if (isConfirmedOfflineWindow && actCurrent === 'OFFLINE' && actStatusSeconds >= 300) {
  alertType = 'SIN_CONEXION_WIFI';
  message = '\u200B\n*Sin Conexión WiFi*\n\n*Nodo EMA:* OFFLINE\n*Nodo Actuador:* OFFLINE';
}
// CASO B: Batería Agotada (EMA lleva >= 10m OFFLINE mientras Actuador está activo o cayó hace < 5m)
else if (isConfirmedOfflineWindow && (actCurrent !== 'OFFLINE' || actStatusSeconds < 300)) {
  alertType = 'BATERIA_AGOTADA';
  message = '\u200B\n*Bateria Agotada*\n\n*Nodo EMA:* OFFLINE';
}
// CASO C: Restablecimiento (EMA pasa de un estado OFFLINE previo a ONLINE/SLEEP en el último minuto)
else if ((emaCurrent === 'ONLINE' || emaCurrent === 'SLEEP') && emaPrev === 'OFFLINE' && emaStatusSeconds <= 60) {
  alertType = 'EMA_RESTABLECIDO';
  message = '\u200B\n*Nodo EMA* Operativo.';
}

if (alertType === 'NONE') {
  return [];
}

return [{ json: { alertType, message } }];
